ALTER TABLE public.students ADD COLUMN guardian_name text NOT NULL DEFAULT '', ADD COLUMN guardian_phone text NOT NULL DEFAULT '', ADD COLUMN guardian_email text NOT NULL DEFAULT '', ADD COLUMN emergency_name text NOT NULL DEFAULT '', ADD COLUMN emergency_phone text NOT NULL DEFAULT '', ADD COLUMN emergency_relationship text NOT NULL DEFAULT '', ADD COLUMN medical_notes text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.can_mark_class(_class text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher') OR (public.has_role(auth.uid(),'teacher') AND EXISTS(SELECT 1 FROM public.teacher_assignments WHERE teacher_id=auth.uid() AND class_name=_class)) $$;
CREATE TABLE public.attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.students(id), attendance_date date NOT NULL DEFAULT CURRENT_DATE, class_name text NOT NULL, status text NOT NULL DEFAULT 'present' CHECK(status IN ('present','absent','late','excused')), note text NOT NULL DEFAULT '', recorded_by uuid NOT NULL DEFAULT auth.uid(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,attendance_date));
GRANT SELECT,INSERT,UPDATE ON public.attendance TO authenticated; GRANT ALL ON public.attendance TO service_role;
ALTER TABLE public.attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY attendance_read ON public.attendance FOR SELECT TO authenticated USING(public.can_mark_class(class_name) OR public.can_view_student(student_id));
CREATE POLICY attendance_insert ON public.attendance FOR INSERT TO authenticated WITH CHECK(public.can_mark_class(class_name) AND recorded_by=auth.uid());
CREATE POLICY attendance_update ON public.attendance FOR UPDATE TO authenticated USING(public.can_mark_class(class_name)) WITH CHECK(public.can_mark_class(class_name) AND recorded_by=auth.uid());
CREATE OR REPLACE FUNCTION public.validate_attendance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.attendance_date>CURRENT_DATE THEN RAISE EXCEPTION 'Attendance cannot be recorded for a future date'; END IF; IF NOT EXISTS(SELECT 1 FROM public.students WHERE id=NEW.student_id AND class_name=NEW.class_name) THEN RAISE EXCEPTION 'Student is not in this class'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER attendance_validation BEFORE INSERT OR UPDATE ON public.attendance FOR EACH ROW EXECUTE FUNCTION public.validate_attendance();
ALTER TABLE public.marks ADD COLUMN review_status text NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','submitted','approved')), ADD COLUMN reviewed_by uuid, ADD COLUMN reviewed_at timestamptz;
UPDATE public.marks SET review_status='approved' WHERE published=true;
CREATE OR REPLACE FUNCTION public.review_marks() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE leader boolean:=public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher'); BEGIN IF TG_OP='UPDATE' AND (NEW.score,NEW.max_score,NEW.subject,NEW.term,NEW.comment,NEW.assessment,NEW.student_id) IS DISTINCT FROM (OLD.score,OLD.max_score,OLD.subject,OLD.term,OLD.comment,OLD.assessment,OLD.student_id) THEN NEW.review_status='draft'; NEW.published=false; NEW.reviewed_by=NULL; NEW.reviewed_at=NULL; END IF; IF NEW.review_status='approved' AND (TG_OP='INSERT' OR OLD.review_status IS DISTINCT FROM NEW.review_status) THEN IF NOT leader THEN RAISE EXCEPTION 'Only school leaders can approve results'; END IF; IF TG_OP='INSERT' OR OLD.review_status<>'submitted' THEN RAISE EXCEPTION 'Submit results before approval'; END IF; NEW.reviewed_by=auth.uid(); NEW.reviewed_at=now(); ELSIF NEW.review_status<>'approved' THEN NEW.reviewed_by=NULL; NEW.reviewed_at=NULL; END IF; IF NEW.published AND (TG_OP='INSERT' OR NOT OLD.published) AND (NOT leader OR NEW.review_status<>'approved') THEN RAISE EXCEPTION 'Results require leadership approval before publication'; END IF; IF TG_OP='UPDATE' AND NEW.review_status='approved' AND OLD.review_status='approved' THEN NEW.reviewed_by=OLD.reviewed_by; NEW.reviewed_at=OLD.reviewed_at; END IF; IF NEW.review_status<>'approved' THEN NEW.published=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER marks_review BEFORE INSERT OR UPDATE ON public.marks FOR EACH ROW EXECUTE FUNCTION public.review_marks();
CREATE POLICY leaders_review_marks ON public.marks FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher'));
ALTER TABLE public.fees ADD COLUMN paid_amount numeric NOT NULL DEFAULT 0;
UPDATE public.fees SET paid_amount=amount WHERE status='paid';
CREATE TABLE public.fee_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fee_id uuid NOT NULL REFERENCES public.fees(id), amount numeric NOT NULL CHECK(amount>0), payment_date date NOT NULL DEFAULT CURRENT_DATE, method text NOT NULL, receipt_no text NOT NULL UNIQUE DEFAULT ('HGA-P-' || to_char(CURRENT_DATE,'YYYY') || '-' || nextval('public.receipt_seq')), recorded_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fee_payments TO authenticated; GRANT ALL ON public.fee_payments TO service_role;
ALTER TABLE public.fee_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payment_read ON public.fee_payments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.fees f WHERE f.id=fee_id AND public.can_view_student(f.student_id)));
INSERT INTO public.fee_payments(fee_id,amount,payment_date,method,receipt_no,recorded_by) SELECT id,amount,COALESCE(paid_on,CURRENT_DATE),COALESCE(payment_method,'Cash'),receipt_no,NULL FROM public.fees WHERE status='paid' AND amount>0 AND receipt_no IS NOT NULL;
CREATE OR REPLACE FUNCTION public.protect_fee_balance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE total numeric; BEGIN SELECT COALESCE(sum(amount),0) INTO total FROM public.fee_payments WHERE fee_id=NEW.id; IF NEW.amount<=0 OR NEW.amount<total THEN RAISE EXCEPTION 'Charge must be positive and cannot be below payments already received'; END IF; NEW.paid_amount=total; NEW.status=CASE WHEN total>=NEW.amount THEN 'paid' ELSE 'unpaid' END; RETURN NEW; END $$;
CREATE TRIGGER a_fee_balance BEFORE INSERT OR UPDATE ON public.fees FOR EACH ROW EXECUTE FUNCTION public.protect_fee_balance();
CREATE OR REPLACE FUNCTION public.record_fee_payment(_fee_id uuid,_amount numeric,_method text,_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.fees; payment_id uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO f FROM public.fees WHERE id=_fee_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Charge not found'; END IF; IF _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) OR _amount>f.amount-f.paid_amount THEN RAISE EXCEPTION 'Payment must be positive and cannot exceed the balance'; END IF; IF _date IS NULL OR _date>CURRENT_DATE OR _method NOT IN ('Cash','Mobile Money','Bank transfer') THEN RAISE EXCEPTION 'Choose a valid date and payment method'; END IF; INSERT INTO public.fee_payments(fee_id,amount,method,payment_date,recorded_by) VALUES(_fee_id,_amount,_method,_date,auth.uid()) RETURNING id INTO payment_id; UPDATE public.fees SET payment_method=_method,paid_on=_date WHERE id=_fee_id; RETURN payment_id; END $$;
REVOKE ALL ON FUNCTION public.record_fee_payment(uuid,numeric,text,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_fee_payment(uuid,numeric,text,date) TO authenticated;
ALTER TABLE public.announcements ADD COLUMN target_student_id uuid REFERENCES public.students(id);
DROP POLICY "family read announcements" ON public.announcements;
CREATE POLICY "family read announcements" ON public.announcements FOR SELECT TO authenticated USING((target_student_id IS NULL AND (class_name IS NULL OR public.in_my_class(class_name))) OR (target_student_id IS NOT NULL AND public.can_view_student(target_student_id)));
CREATE TABLE public.school_calendar(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, kind text NOT NULL DEFAULT 'event' CHECK(kind IN ('event','holiday','exam')), starts_on date NOT NULL, ends_on date NOT NULL, class_name text, target_student_id uuid REFERENCES public.students(id), details text NOT NULL DEFAULT '', created_by uuid NOT NULL DEFAULT auth.uid(), CHECK(ends_on>=starts_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.school_calendar TO authenticated; GRANT ALL ON public.school_calendar TO service_role;
ALTER TABLE public.school_calendar ENABLE ROW LEVEL SECURITY;
CREATE POLICY calendar_read ON public.school_calendar FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) OR (target_student_id IS NULL AND (class_name IS NULL OR public.in_my_class(class_name))) OR public.can_view_student(target_student_id));
CREATE POLICY calendar_manage ON public.school_calendar FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher')) WITH CHECK((public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'head_teacher')) AND created_by=auth.uid());